def sum_of_prime_factors_with_multiplicity(n):
    total = 0
    x = n
    p = 2
    while p * p <= x:
        while x % p == 0:
            total += p
            x //= p
        p += 1
    if x > 1:
        total += x
    return total

def prime_factors(n):
    n = abs(n)
    factors = []
    d = 2
    while d * d <= n:
        while n % d == 0:
            factors.append(d)
            n //= d
        d += 1
    if n > 1:
        factors.append(n)
    return factors

