def wrap_fixed_lines(text, width, max_lines):
    words = text.split()
    lines = []
    cur = ""
    for word in words:
        if not cur:
            cur = word
        elif len(cur) + 1 + len(word) <= width:
            cur += " " + word
        else:
            lines.append(cur)
            cur = word
    if cur:
        lines.append(cur)
    if len(lines) > max_lines:
        lines = lines[:max_lines]
        last = lines[-1]
        if len(last) + 3 <= width:
            lines[-1] = last + "..."
        else:
            lines[-1] = last[:max(0, width - 3)] + "..."
    return lines

