def count_divisors_of_factorial(n):
    if n <= 1:
        return 1
    limit = n
    is_comp = [False] * (limit + 1)
    primes = []
    for p in range(2, limit + 1):
        if not is_comp[p]:
            primes.append(p)
            for m in range(p * p, limit + 1, p):
                is_comp[m] = True
    result = 1
    for p in primes:
        exp = 0
        pw = p
        while pw <= n:
            exp += n // pw
            pw *= p
        result *= (exp + 1)
    return result

def decimal_to_base(n, base):
    if n == 0:
        return "0"
    digits = "0123456789abcdefghijklmnopqrstuvwxyz"
    neg = n < 0
    n = abs(n)
    out = []
    while n:
        out.append(digits[n % base])
        n //= base
    if neg:
        out.append('-')
    return ''.join(reversed(out))

def shift_time_by_minutes(hh, mm, offset_minutes):
