def group_by_key_range(d, low, high):
    res = {"in_range": [], "out_range": []}
    for k, v in d.items():
        if low <= v <= high:
            res["in_range"].append(k)
        else:
            res["out_range"].append(k)
    res["in_range"] = sorted(res["in_range"])
    res["out_range"] = sorted(res["out_range"])
    return res
